    # --- 农药残留限量 (7项) ---
    {
        "standard_code": "GB 2763-2012",
        "title": "食品安全国家标准 GB 2763-2012",
        "category": "农药残留限量",
        "priority": "P0-核心必备",
        "status": "现行",
        "publish_date": "2012-06-30",
        "implementation_date": "2013-06-01",
        "link": "https://sppt.cfsa.net.cn:8086/",
        "summary": "规定食品中多种农药的最大残留限量要求，涵盖有机氯、有机磷、拟除虫菊酯等农药。",
        "content": "本标准规定了数百种农药在数百种（类）食品中的最大残留限量，涵盖有机氯、有机磷、拟除虫菊酯、氨基甲酸酯等农药残留限量指标及检验方法。",
    },
