@router.get("/standards", summary="查询食品安全国家标准目录")
async def get_food_safety_standards(
    category: Optional[str] = Query(default=None, description="按类别筛选"),
):
    """
    返回食品安全国家标准目录（涵盖 GB 2760/2761/2762/2763 等核心标准）
    支持按类别筛选：全部 / 食品添加剂 / 农药残留 / 污染物限量 / 微生物控制 / 乳制品 / 饮料 / 调味品 / 油脂 / 婴幼儿食品 / 冷冻食品 / 蛋白质类 / 食品接触材料 / 兽药残留
    """
    standards = FOOD_SAFETY_STANDARDS
    if category and category != "全部":
        standards = [s for s in standards if s["category"] == category]
    return {
        "success": True,
        "data": {
            "source": "国家卫生健康委员会 · FoodTalks 食品伙伴网",
            "count": len(standards),
            "standards": standards,
        },
    }


@router.get("/food-homology", summary="查询药食同源目录完整信息")
async def get_food_homology(
    name: Optional[str] = Query(default=None, description="按名称搜索"),
):
    """
    返回药食同源物质目录完整信息
    含拉丁学名、适用人群、每日限量、用法形式及禁忌事项
    数据来源：国家卫健委公告及 TCMSP 中药系统药理学数据库
    """
    materials = FOOD_HOMOLOGY_MATERIALS
    if name:
        materials = [m for m in materials if name in m["name"] or name in m.get("latin_name", "")]
    return {
        "success": True,
        "data": {
            "source": "国家卫健委药食同源目录公告（2025版）共106种",
            "count": len(materials),
            "materials": materials,
        },
    }

